INSERT INTO changelog (title, body, created_at) VALUES ('Вкладка Meta клієнта — компактно', 'Клієнт → Meta → Огляд: зверху 4 цифри за 7 днів (з динамікою), під ними одна смужка «30 днів» (ліди, витрати, ціна ліда, CTR, ціна кліку, CPM, охоплення, частота). «Головне» — 3 пункти, решта по кліку. Графіки по днях лишились. Кампанії, По місяцях (з мініграфіком лідів), Відхилені оголошення і Анкета послуги — плитки, повна таблиця у віконці. Проблеми кабінету — одним рядком замість великих плашок. Сторінка на третину коротша.', datetime('now'));
